'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now = new Date();
const localDate = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today = localDate(now), yearStart = `${now.getFullYear()}-01-01`;
const currency = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2,minimumFractionDigits:0}).format((n||0)/100);
const number = n => new Intl.NumberFormat('en-IN',{maximumFractionDigits:3}).format(n||0);
const shortMoney = n => Math.abs(n)>=10000000 ? `₹${(n/10000000).toFixed(1)}L` : Math.abs(n)>=100000 ? `₹${(n/100000).toFixed(0)}k` : currency(n);
const displayDate = d => d ? new Date(d.slice(0,10)+'T12:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}) : '—';
const initials = n => String(n||'?').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const paths = {
 chair:'M6 12V4h12v8M4 12h16v5H4zM6 17v4m12-4v4M8 7h8',home:'M3 10l9-7 9 7v11H3zM9 21v-8h6v8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',bag:'M4 7h16l1 14H3zM8 7V5a4 4 0 018 0v2',cart:'M2 3h3l3 12h10l3-9H6M9 20h.01M18 20h.01',file:'M14 2H5v20h14V7zM14 2v5h5M8 12h8m-8 4h8',wallet:'M20 7H4V4h14v3M4 7v14h17V7zM16 12h5v5h-5z',users:'M16 21v-3a4 4 0 00-4-4H6a4 4 0 00-4 4v3M9 10a4 4 0 100-8 4 4 0 000M17 3a4 4 0 010 7m2 4a4 4 0 013 4v3',box:'M3 7l9-5 9 5v11l-9 5-9-5zM3 7l9 5 9-5M12 12v11M8 4l9 5',book:'M3 3h7a3 3 0 012 3v16a3 3 0 00-3-3H3zM21 3h-7a3 3 0 00-2 3v16a3 3 0 013-3h6z',chart:'M3 3v18h18M7 15l4-5 4 3 5-8',target:'M12 2a10 10 0 100 20 10 10 0 000M12 6a6 6 0 100 12 6 6 0 000M12 10a2 2 0 100 4 2 2 0 000',settings:'M12 8a4 4 0 100 8 4 4 0 000M8 3l-1 3-3 1v4l2 1-2 2v4l3 1 1 3h7l1-3 3-1v-4l-2-2 2-1V7l-3-1-1-3z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',down:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',search:'M10 3a7 7 0 100 14 7 7 0 000M15 15l6 6',close:'M6 6l12 12M6 18L18 6',check:'M5 12l4 4L19 6',leaf:'M20 3C9 2 2 10 6 17s15-1 14-14zM5 21l10-12',logout:'M9 3H3v18h6M10 12h11m-4-4 4 4-4 4',clock:'M12 2a10 10 0 100 20 10 10 0 000M12 6v6l4 2',bank:'M2 8l10-6 10 6H2M4 10v8m5-8v8m6-8v8m5-8v8M2 21h20',trend:'M3 17l6-6 4 4 8-10M15 5h6v6',edit:'M15 4l5 5M4 15L17 2l5 5L9 20l-7 2z',archive:'M3 3h18v5H3zM5 8v13h14V8M9 12h6',menu:'M3 6h18M3 12h18M3 18h18',print:'M6 9V2h12v7M6 17H3V9h18v8h-3M6 14h12v8H6z',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const button = (label,action,classes='',attrs='') => `<button class="btn ${classes}" data-action="${action}" ${attrs}>${label}</button>`;
const badge = (label,color='') => `<span class="badge ${color}">${esc(label)}</span>`;
const avatar = (name,image='') => image ? `<img src="${esc(image)}" alt="">` : `<span class="avatar">${esc(initials(name))}</span>`;
const statusBadge = d => d.paid>=d.total ? badge('Paid','green') : d.due_date<today ? badge('Overdue','red') : d.paid>0 ? badge('Part paid','blue') : badge('Awaiting payment','amber');
const active = table => (state.data[table]||[]).filter(x=>x.active);
const find = (table,id) => (state.data[table]||[]).find(x=>x.id==id);
const state={user:null,csrf:'',data:{},report:null,page:'dashboard',query:'',filter:'all',reportTab:'pnl',start:yearStart,end:today,form:null};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
async function api(path,method='GET',data){const res=await fetch('/api'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},...(data!==undefined?{body:JSON.stringify(data)}:{})});let result;try{result=await res.json()}catch{throw Error('The server could not complete this request. Please try again.')}if(!res.ok)throw Error(result.error||'Something went wrong.');return result}
async function boot(){try{const s=await api('/session');state.csrf=s.csrf;state.user=s.user;if(!s.user){renderLogin(s.needs_setup);return}await load();state.page=location.hash.slice(1)|| (state.user.role==='contact'?'portal':'dashboard');if(state.user.role==='contact')state.page='portal';render()}catch(e){$('#app').innerHTML=`<div class="error-page"><h1>Unable to open the workspace</h1><p>${esc(e.message)}</p>${button('Try again','retry','primary')}</div>`}}
async function load(){const contact=state.user.role==='contact';const [data,report]=await Promise.all([api('/data'),contact?null:api(`/reports?start=${state.start}&end=${state.end}`)]);state.data=data;state.report=report}
async function refresh(message){await load();render();if(message)toast(message)}
function renderLogin(setup){$('#app').innerHTML=`<div class="login-layout"><section class="login-art"><div class="brand"><span class="brand-symbol">${icon('chair')}</span><div>urban<span style="font-weight:350"> furniture</span><small>BOOKS & BUSINESS</small></div></div><div><div class="eyebrow">MADE FOR THE WAY YOU WORK</div><h1>Beautiful furniture.<br>Balanced books.</h1><p>A considered space for your business. Bring your sales, purchases, and finances together, one entry at a time.</p></div><small>URBAN FURNITURE &nbsp; / &nbsp; YOUR BUSINESS, IN BALANCE</small><div class="arch"></div></section><section class="login-form"><div class="login-inner"><div class="eyebrow">${setup?'LET’S BUILD YOUR WORKSPACE':'WELCOME BACK'}</div><h2>${setup?'A fresh start.':'Good to see you.'}</h2><p>${setup?'Set up your business owner account. You can invite your accountant and create contact accounts inside.':'Sign in to your Urban Furniture workspace.'}</p><form id="auth-form" data-setup="${setup}">${setup?field('Your name','name','text','',{required:true,autocomplete:'name'}):''}${field('Email address','email','email','',{required:true,autocomplete:'username'})}${field('Password','password','password','',{required:true,minlength:setup?10:1,autocomplete:setup?'new-password':'current-password'})}<div class="form-error" id="auth-error" role="alert"></div><button class="btn primary" type="submit">${setup?'Create workspace':'Sign in'} ${icon('arrow')}</button></form><div class="login-foot">${icon('shield')} &nbsp; Your books. Your local workspace.</div></div></section></div>`}
const navGroups=[['WORKSPACE',[['dashboard','Overview','grid'],['sales','Sales orders','bag'],['purchases','Purchase orders','cart'],['invoices','Invoices & bills','file'],['payments','Payments','wallet']]],['MANAGE',[['contacts','Contacts','users'],['products','Products','box'],['accounting','Accounting','book'],['budgets','Budgets','target'],['reports','Reports','chart']]],['ORGANIZATION',[['settings','Settings','settings']]]];
const pageNames={dashboard:'Overview',sales:'Sales orders',purchases:'Purchase orders',invoices:'Invoices & bills',payments:'Payments',contacts:'Contacts',products:'Products',accounting:'Accounting',budgets:'Budgets',reports:'Reports',settings:'Settings',portal:'My invoices & bills'};
function render(){if(!pageNames[state.page])state.page='dashboard';const contact=state.user.role==='contact';const nav=contact?[['YOUR ACCOUNT',[['portal','My invoices & bills','file'],['settings','Account settings','settings']]]]:navGroups;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-symbol">${icon('chair')}</span><div>urban furniture<small>BOOKS & BUSINESS</small></div></div><div class="workspace"><div class="workspace-icon">${icon('home')}</div><div><strong>Urban Furniture</strong><small>${contact?'Contact portal':'Business workspace'}</small></div></div><nav>${nav.map(([title,items])=>`<div class="nav-label">${title}</div>${items.map(([id,label,ico])=>`<button class="nav-item ${state.page===id?'active':''}" data-action="navigate" data-page="${id}">${icon(ico)}<span>${label}</span>${id==='invoices'?`<span class="nav-count">${state.data.documents.filter(d=>d.paid<d.total).length||''}</span>`:''}</button>`).join('')}`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><h3>Your books, in balance.</h3><p>${contact?'A simple view of your invoices, bills, and payment history.':'Every transaction has a place. Every decision, a clearer picture.'}</p><button data-action="help">Explore your workspace ${icon('arrow')}</button></div><div class="user">${avatar(state.user.name)}<div><div class="user-name">${esc(state.user.name)}</div><small>${{admin:'Business owner',accountant:'Accountant',contact:'Contact account'}[state.user.role]}</small></div><button data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="flex"><button class="icon-btn mobile-menu" data-action="mobile-nav" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/</span> <strong>${pageNames[state.page]}</strong></div></div><div class="top-actions"><span class="date-display">${now.toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'long',year:'numeric'})}</span><span class="pill"><span class="dot"></span> ${contact?'Contact portal':'INR · Indian Rupee'}</span></div></header><div class="content" id="page">${renderPage()}</div></main></div>`}
function head(title,subtitle,action='',eyebrow='YOUR BUSINESS, AT A GLANCE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`}
function footer(){return '<footer class="footer"><span>Thoughtfully organized. Confidently balanced.</span><span>Urban Furniture &nbsp; © '+now.getFullYear()+'</span></footer>'}
function empty(title,message,action=''){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${message}</p>${action}</div>`}
function table(headers,body){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`}
function stat(label,value,note,ico='wallet',dark=false){return `<div class="stat ${dark?'dark':''}"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function renderPage(){switch(state.page){case'dashboard':return dashboard();case'sales':case'purchases':return ordersPage();case'invoices':case'portal':return documentsPage();case'payments':return paymentsPage();case'contacts':case'products':return masterPage(state.page);case'accounting':return accountingPage();case'budgets':return budgetsPage();case'reports':return reportsPage();case'settings':return settingsPage();default:return dashboard()}}
function dashboard(){const d=state.data,r=state.report;const receivable=d.documents.filter(x=>x.kind==='sale').reduce((s,x)=>s+x.total-x.paid,0),payable=d.documents.filter(x=>x.kind==='purchase').reduce((s,x)=>s+x.total-x.paid,0);const cash=r.accounts.filter(x=>['cash','bank'].includes(x.system_key)).reduce((s,x)=>s+x.balance,0);const outstanding=d.documents.filter(x=>x.kind==='sale'&&x.paid<x.total).length;const cashAccounts=r.accounts.filter(x=>['cash','bank'].includes(x.system_key));
 return head(`A little clarity. A lot of possibility.`,`Here’s how your business is doing. Let’s make today count.`,button(`${icon('plus')} New transaction`,'new-order','primary','data-kind="sale"'))+`<div class="overview-banner"><div class="flex"><div class="leaf-icon">${icon('leaf')}</div><div><strong>Good ${now.getHours()<12?'morning':now.getHours()<17?'afternoon':'evening'}, ${esc(state.user.name.split(' ')[0])}. Your business, at a glance.</strong><p>Financial overview for ${displayDate(state.start)} – ${displayDate(state.end)}</p></div></div>${button(`View reports ${icon('arrow')}`,'navigate','text','data-page="reports"')}</div><div class="stat-grid">${stat('Total revenue',currency(r.income),'<b>Accrual basis</b> Sales excluding tax','trend',true)}${stat('Total expenses',currency(r.expenses),'Purchases & operating expenses','cart')}${stat('Outstanding invoices',currency(receivable),`<b>${outstanding} open</b> Customer balances, all dates`,'file')}${stat('Net profit',currency(r.profit),'Revenue less expenses for the period','chart')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Revenue & expenses</h2><p>A little perspective on your business performance</p></div><div class="legend"><span><i></i>Revenue</span><span><i class="light"></i>Expenses</span></div></div><div class="panel-body">${chart(r)}<div class="chart-summary"><div><small>TOTAL REVENUE</small><strong>${currency(r.income)}</strong></div><div><small>TOTAL EXPENSES</small><strong>${currency(r.expenses)}</strong></div><div><small>NET MARGIN</small><strong>${r.income?((r.profit/r.income)*100).toFixed(1)+'%':'—'}</strong></div></div></div></section><section class="panel"><div class="panel-head"><div><h2>A healthy perspective</h2><p>Your balances, all in one place</p></div>${icon('wallet')}</div><div class="panel-body">${cashAccounts.map(a=>`<div class="balance-section"><div class="flex"><span class="balance-icon">${icon(a.system_key==='bank'?'bank':'wallet')}</span><div>${esc(a.name)}<small>Balance as of ${displayDate(state.end)}</small></div></div><strong>${currency(a.balance)}</strong></div>`).join('')}<div class="balance-section"><span>Outstanding vendor bills</span><strong>${currency(payable)}</strong></div><div class="balance-foot">${icon('check')} ${r.balance_difference===0?'Your balance sheet is in balance.':'Review your balance sheet.'}</div></div></section></div><section class="panel mb"><div class="panel-head"><div><h2>Recent invoices & bills</h2><p>The latest movement in your business</p></div>${button(`View all ${icon('arrow')}`,'navigate','text','data-page="invoices"')}</div>${d.documents.length?documentTable(d.documents.slice(0,5),true):empty('Your next chapter starts here','Create a purchase order to receive stock, then make your first sale.',button('Create purchase order','new-order','primary','data-kind="purchase"'))}<div class="table-footer"><span>${d.documents.length} total invoices & bills</span><span>Amounts include tax</span></div></section><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>A good place to start</h2><span class="muted">${icon('plus')}</span></div><div class="panel-body"><div class="quick-grid">${[['bag','New sale','new-order','data-kind="sale"'],['cart','New purchase','new-order','data-kind="purchase"'],['users','Add contact','new-master','data-table="contacts"'],['chart','View reports','navigate','data-page="reports"']].map(([ico,title,act,attrs])=>`<button class="quick" data-action="${act}" ${attrs}>${icon(ico)}${title}</button>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>Latest activity</h2><span class="muted">${icon('clock')}</span></div><div class="panel-body">${d.audit.slice(0,2).map(a=>`<div class="activity"><span class="activity-mark">${icon('check')}</span><div>${esc(a.action)} ${esc(a.entity==='system'?'':a.entity)}<small>${esc(a.user_name||'System')}</small></div><time>${displayDate(a.created_at)}</time></div>`).join('')||'<p class="subtitle">Your activity will appear here.</p>'}</div></section></div>`+footer()}
function chart(r){const months=[];for(let i=5;i>=0;i--){const dt=new Date(now.getFullYear(),now.getMonth()-i,1);months.push({key:localDate(dt).slice(0,7),label:dt.toLocaleDateString('en-IN',{month:'short'}),income:0,expense:0})}const types=Object.fromEntries(r.accounts.map(a=>[a.code,a.type]));r.ledger.forEach(l=>{const m=months.find(m=>l.date.startsWith(m.key));if(m){if(types[l.code]==='Income')m.income+=l.credit-l.debit;if(types[l.code]==='Expense')m.expense+=l.debit-l.credit}});const max=Math.max(100,...months.flatMap(m=>[m.income,m.expense]));return `<div class="chart" role="img" aria-label="Monthly revenue and expense chart. Exact totals are shown below."><div class="chart-axis"><span>${shortMoney(max)}</span><span>${shortMoney(max*.66)}</span><span>${shortMoney(max*.33)}</span><span>₹0</span></div><div class="chart-bars">${months.map(m=>`<div class="chart-group"><div class="chart-bar" style="height:${Math.max(0,m.income/max*100)}%" title="${m.label} revenue: ${currency(m.income)}"></div><div class="chart-bar light" style="height:${Math.max(0,m.expense/max*100)}%" title="${m.label} expenses: ${currency(m.expense)}"></div><small>${m.label}</small></div>`).join('')}</div></div>`}
function toolbar(tabs=[]){return `<div class="toolbar"><div class="tabs">${tabs.map(([key,label])=>`<button class="tab ${state.filter===key?'active':''}" data-action="filter" data-filter="${key}">${label}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="search" placeholder="Search this view…" aria-label="Search this view" value="${esc(state.query)}"></label></div>`}
function filtered(list){const q=state.query.toLowerCase();return list.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(q)))}
function ordersPage(){const sale=state.page==='sales';let list=state.data.orders.filter(x=>x.kind===(sale?'sale':'purchase'));if(state.filter!=='all')list=list.filter(x=>x.status===state.filter);list=filtered(list);return head(sale?'From a good idea to a great sale.':'Good business starts at the source.',sale?'Build sales orders, then turn them into customer invoices.':'Track vendor orders and receive stock when you post a bill.',button(`${icon('plus')} ${sale?'Sales':'Purchase'} order`,'new-order','primary',`data-kind="${sale?'sale':'purchase'}"`),sale?'SALES ORDERS':'PURCHASE ORDERS')+toolbar([['all','All orders'],['draft','Draft'],['posted','Converted'],['cancelled','Cancelled']])+`<section class="panel">${list.length?table(['Order','Contact','Order date','Due date','Status','Total',''],list.map(o=>`<tr><td><strong>${esc(o.number)}</strong></td><td>${esc(o.contact_name)}</td><td>${displayDate(o.date)}</td><td>${displayDate(o.due_date)}</td><td>${badge(o.status==='posted'?'Converted':o.status,o.status==='posted'?'green':o.status==='draft'?'amber':'')}</td><td class="num"><strong>${currency(o.total)}</strong></td><td>${button('View','view-order','small',`data-id="${o.id}"`)}</td></tr>`).join('')):empty('No orders here yet','Create an order using your contacts and products. Draft orders do not affect your books.')}<div class="table-footer">${list.length} orders · Stock and ledgers update on conversion</div></section>`+footer()}
function documentTable(list,compact=false){return table(['Document','Contact','Date',...(compact?[]:['Due date']),'Amount','Status',''],list.map(d=>`<tr><td><strong>${esc(d.number)}</strong><div style="font-size:9px;margin-top:4px;color:#a0a792">${d.kind==='sale'?'Customer invoice':'Vendor bill'}</div></td><td><span class="contact-cell">${avatar(d.contact_name)}${esc(d.contact_name)}</span></td><td>${displayDate(d.date)}</td>${compact?'':`<td>${displayDate(d.due_date)}</td>`}<td class="num"><strong>${currency(d.total)}</strong>${d.paid>0&&d.paid<d.total?`<div style="font-size:9px;margin-top:4px">${currency(d.total-d.paid)} due</div>`:''}</td><td>${statusBadge(d)}</td><td>${button('View','view-document','small',`data-id="${d.id}"`)}</td></tr>`).join(''))}
function documentsPage(){const contact=state.user.role==='contact';let list=state.data.documents;if(state.filter==='sale'||state.filter==='purchase')list=list.filter(x=>x.kind===state.filter);if(state.filter==='unpaid')list=list.filter(x=>x.paid<x.total);if(state.filter==='paid')list=list.filter(x=>x.paid>=x.total);list=filtered(list);const due=state.data.documents.filter(d=>d.kind==='sale').reduce((s,d)=>s+d.total-d.paid,0);return head(contact?'Everything, in one place.':'Every invoice. Every detail.',contact?'View your invoices and bills, record a payment, and download copies.':'Keep track of what’s paid, what’s pending, and what’s next.',contact?'':button(`${icon('plus')} New sales order`,'new-order','primary','data-kind="sale"'),contact?'YOUR CONTACT PORTAL':'INVOICES & BILLS')+(contact?`<div class="stat-grid">${stat('Your amount due',currency(due),'Customer invoice balance','wallet',true)}${stat('Your documents',state.data.documents.length,'Invoices and vendor bills','file')}</div><div class="notice">Payments entered here are bookkeeping records. Bank transfers and cash must be settled separately; this app does not charge a card or move money.</div>`:'')+toolbar([['all','All documents'],['sale','Invoices'],['purchase','Bills'],['unpaid','Unpaid'],['paid','Paid']])+`<section class="panel">${list.length?documentTable(list):empty('All clear for now','Invoices and bills appear here after an order is converted.')}<div class="table-footer">${list.length} documents · INR</div></section>`+footer()}
function paymentsPage(){const list=filtered(state.data.payments);return head('A clear view of every payment.','All receipts and vendor payments, linked to their original document.','','MONEY MOVEMENT')+toolbar()+`<section class="panel">${list.length?table(['Payment','Document','Contact','Date','Method','Reference','Amount'],list.map(p=>`<tr><td><strong>${p.number}</strong></td><td>${button(p.document_number,'view-document','text',`data-id="${p.document_id}"`)}</td><td>${esc(p.contact_name)}</td><td>${displayDate(p.date)}</td><td>${badge(p.method,p.method==='Bank'?'blue':'green')}</td><td>${esc(p.reference)||'—'}</td><td class="num"><strong>${p.kind==='sale'?'+':'−'}${currency(p.amount)}</strong></td></tr>`).join('')):empty('Every payment has a place','Open an invoice or bill and choose Record payment to get started.',button('View invoices & bills','navigate','primary','data-page="invoices"'))}<div class="table-footer">${list.length} payments · Receipts (+) and vendor payments (−)</div></section>`+footer()}
const masterTitles={contacts:'Contacts',products:'Products',accounts:'Chart of accounts',journals:'Journals',analytics:'Analytic accounts',budgets:'Budgets'};
function masterActions(table,x){return state.user.role==='admin'?`<div class="flex">${button(icon('edit'),'edit-master','small',`data-table="${table}" data-id="${x.id}" aria-label="Edit ${esc(x.name)}"`)}${button(x.active?icon('archive'):'Restore','archive','small',`data-table="${table}" data-id="${x.id}" aria-label="${x.active?'Archive':'Restore'} ${esc(x.name)}"`)}</div>`:''}
function masterTable(table,list){if(!list.length)return empty('A little space for something new',`Add ${masterTitles[table].toLowerCase()} to connect your everyday transactions.`);let headers,body;
 if(table==='contacts'){headers=['Contact','Type','Email & phone','Location','Status',''];body=list.map(x=>`<tr><td><span class="contact-cell">${avatar(x.name,x.image)}<strong>${esc(x.name)}</strong></span></td><td>${badge(x.type,x.type==='Customer'?'green':x.type==='Vendor'?'blue':'amber')}</td><td>${esc(x.email)||'—'}<div style="font-size:9px;margin-top:5px">${esc(x.mobile)}</div></td><td>${esc([x.city,x.state].filter(Boolean).join(', '))||'—'}</td><td>${badge(x.active?'Active':'Archived',x.active?'green':'')}</td><td>${masterActions(table,x)}</td></tr>`).join('')}
 if(table==='products'){headers=['Product','Category','Type','Sales price','Cost','On hand',''];body=list.map(x=>`<tr><td><span class="contact-cell"><span class="avatar">${icon('chair')}</span><strong>${esc(x.name)}</strong></span>${x.active?'':badge('Archived')}</td><td>${esc(x.category)||'—'}</td><td>${badge(x.type)}</td><td class="num">${currency(x.sales_price)}</td><td class="num">${currency(x.cost)}</td><td class="num">${x.type==='Service'?'—':number(state.data.stock.find(s=>s.id===x.id)?.quantity||0)}</td><td>${masterActions(table,x)}</td></tr>`).join('')}
 if(table==='accounts'){headers=['Code','Account name','Type','Status',''];body=list.map(x=>`<tr><td>${esc(x.code)}</td><td><strong>${esc(x.name)}</strong>${x.system_key?' <small class="muted">· System</small>':''}</td><td>${badge(x.type)}</td><td>${badge(x.active?'Active':'Archived',x.active?'green':'')}</td><td>${masterActions(table,x)}</td></tr>`).join('')}
 if(table==='journals'){headers=['Journal','Type','Default debit','Default credit','Status',''];body=list.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${badge(x.type)}</td><td>${esc(find('accounts',x.debit_account_id)?.name)}</td><td>${esc(find('accounts',x.credit_account_id)?.name)}</td><td>${badge(x.active?'Active':'Archived',x.active?'green':'')}</td><td>${masterActions(table,x)}</td></tr>`).join('')}
 if(table==='analytics'){headers=['Analytic account','Type','Status',''];body=list.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${badge(x.type)}</td><td>${badge(x.active?'Active':'Archived',x.active?'green':'')}</td><td>${masterActions(table,x)}</td></tr>`).join('')}
 if(table==='budgets'){headers=['Budget','Period','Analytic account','Responsible','Planned',''];body=list.map(x=>`<tr><td><strong>${esc(x.name)}</strong>${x.active?'':badge('Archived')}</td><td>${displayDate(x.start_date)}<br><small>to ${displayDate(x.end_date)}</small></td><td>${esc(find('analytics',x.analytic_id)?.name)}</td><td>${esc(x.responsible)}</td><td class="num">${currency(x.planned)}</td><td>${masterActions(table,x)}</td></tr>`).join('')}
 return tableHtml(headers,body)
}
const tableHtml=table;
function masterPage(type){let list=state.data[type];if(state.filter==='all')list=list.filter(x=>x.active);else if(state.filter==='archived')list=list.filter(x=>!x.active);else list=list.filter(x=>x.active&&x.type===state.filter);list=filtered(list);return head(type==='contacts'?'Good relationships. Great business.':'A collection worth keeping track of.',type==='contacts'?'Your customers, vendors, and the people behind every transaction.':'Manage your furniture, services, prices, and stock in one place.',button(`${icon('plus')} Add ${type==='contacts'?'contact':'product'}`,'new-master','primary',`data-table="${type}"`),masterTitles[type].toUpperCase())+toolbar(type==='contacts'?[['all','Active contacts'],['Customer','Customers'],['Vendor','Vendors'],['Both','Both'],['archived','Archived']]:[['all','Active products'],['Goods','Goods'],['Service','Services'],['Combo','Combos'],['archived','Archived']])+`<section class="panel">${masterTable(type,list)}<div class="table-footer">${list.length} ${type}</div></section>`+footer()}
function accountingPage(){const tab=['entries','accounts','journals'].includes(state.filter)?state.filter:'entries';const create=tab==='entries'?button(`${icon('plus')} Journal entry`,'new-entry','primary'):button(`${icon('plus')} Add ${tab==='accounts'?'account':'journal'}`,'new-master','primary',`data-table="${tab}"`);let list=filtered(state.data[tab]);return head('The foundation of balanced books.','Every entry follows double-entry accounting. Posted records are immutable.',create,'ACCOUNTING')+toolbar([['entries','Journal entries'],['accounts','Chart of accounts'],['journals','Journals']])+`<section class="panel">${tab==='entries'?(list.length?table(['Entry','Date','Journal','Reference','Source','Debit / credit',''],list.map(e=>`<tr><td><strong>${e.number}</strong></td><td>${displayDate(e.date)}</td><td>${esc(e.journal_name)}</td><td>${esc(e.reference)}</td><td>${badge(e.source,e.source==='manual'?'amber':'green')}</td><td class="num">${currency(e.total)}</td><td>${button('View','view-entry','small',`data-id="${e.id}"`)}</td></tr>`).join('')):empty('Your books begin here','Posting invoices, bills, and payments will automatically create balanced entries.')):masterTable(tab,list)}<div class="table-footer">${list.length} records · ${tab==='entries'?'Debit equals credit for every entry':'Archive records to preserve transaction history'}</div></section>`+footer()}
function budgetsPage(){const tab=state.filter==='analytics'?'analytics':'budgets';return head('Make room for what’s next.','Plan income and spending, then measure actuals against your targets.',button(`${icon('plus')} ${tab==='budgets'?'New budget':'Analytic account'}`,'new-master','primary',`data-table="${tab}"`),'BUDGETS & PLANNING')+toolbar([['budgets','Budgets'],['analytics','Analytic accounts']])+`<section class="panel">${masterTable(tab,filtered(state.data[tab]))}</section>`+footer()}
function reportsPage(){const r=state.report;const section=(title,rows,totalLabel,total)=>`<section class="panel"><div class="panel-head"><h2>${title}</h2></div><div class="panel-body">${rows.map(a=>`<div class="report-line"><span>${esc(a.name)}</span><strong>${currency(a.value)}</strong></div>`).join('')}<div class="report-line total"><span>${totalLabel}</span><span>${currency(total)}</span></div></div></section>`;let content='';
 if(state.reportTab==='pnl')content=`<div class="stat-grid">${stat('Revenue',currency(r.income),'Excluding tax','trend')}${stat('Expenses',currency(r.expenses),'Purchases & operating costs','cart')}${stat('Net profit',currency(r.profit),'Accrual basis','chart',true)}</div><div class="two-col">${section('Income',r.accounts.filter(a=>a.type==='Income').map(a=>({name:a.name,value:-a.period_balance})),'Total income',r.income)}${section('Expenses',r.accounts.filter(a=>a.type==='Expense').map(a=>({name:a.name,value:a.period_balance})),'Total expenses',r.expenses)}</div><div class="notice">Purchases are expensed when vendor bills are posted, following the supplied requirements. This P&L does not use inventory capitalization or cost-of-goods-sold valuation. Tax is recorded separately.</div>`;
 if(state.reportTab==='balance')content=`<div class="overview-banner"><div><strong>${r.balance_difference===0?'Everything adds up.':'Balance difference: '+currency(r.balance_difference)}</strong><p>Assets = Liabilities + Capital + Cumulative earnings · As of ${displayDate(r.end)}</p></div>${icon('check')}</div><div class="two-col">${section('Assets',r.accounts.filter(a=>a.type==='Asset').map(a=>({name:a.name,value:a.balance})),'Total assets',r.assets)}${section('Liabilities & equity',[...r.accounts.filter(a=>['Liability','Capital'].includes(a.type)).map(a=>({name:a.name,value:-a.balance})),{name:'Cumulative earnings',value:r.earnings}],'Total liabilities & equity',r.liabilities+r.capital+r.earnings)}</div>`;
 if(state.reportTab==='budget')content=`<div class="notice">Planned amounts cover the full budget period. Actuals use the overlap of the selected dates and each budget’s dates; planned amounts are not prorated. Variance = actual − planned. Positive variance is favorable for income and unfavorable for expenses.</div><section class="panel">${r.budgets.length?table(['Budget / analytic account','Type','Planned','Actual','Variance','Progress'],r.budgets.map(b=>`<tr><td><strong>${esc(b.name)}</strong><div class="subtitle">${esc(b.analytic_name)}</div></td><td>${badge(b.analytic_type)}</td><td class="num">${currency(b.planned)}</td><td class="num">${currency(b.actual)}</td><td class="num">${badge(currency(b.variance),((b.analytic_type==='Income'&&b.variance>=0)||(b.analytic_type==='Expense'&&b.variance<=0))?'green':'amber')}</td><td>${b.planned?Math.round(b.actual/b.planned*100)+'%':'—'}<div class="progress"><div style="width:${b.planned?Math.max(0,Math.min(100,b.actual/b.planned*100)):0}%"></div></div></td></tr>`).join('')):empty('No budgets in this period','Create a budget and assign an analytic account to your orders or journal entries.')}</section>`;
 if(state.reportTab==='stock')content=`<div class="notice">Stock quantities are as of ${displayDate(r.end)}. Goods and combos are tracked as whole products; services do not affect stock. Indicative value uses current product cost and is not an inventory ledger balance.</div><section class="panel">${r.stock.length?table(['Product','Category','On hand','Current unit cost','Indicative value'],r.stock.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.category)||'—'}</td><td class="num">${number(s.quantity)}</td><td class="num">${currency(s.cost)}</td><td class="num">${currency(Math.round(s.quantity*s.cost))}</td></tr>`).join('')):empty('Nothing on the shelves yet','Add goods and post a vendor bill to receive stock.')}</section>`;
 if(state.reportTab==='ledger')content=`<section class="panel">${r.ledger.length?table(['Date','Entry','Reference','Account','Debit','Credit'],r.ledger.map(l=>`<tr><td>${displayDate(l.date)}</td><td>${l.number}</td><td>${esc(l.reference)}</td><td>${esc(l.code)} · ${esc(l.account)}</td><td class="num">${l.debit?currency(l.debit):'—'}</td><td class="num">${l.credit?currency(l.credit):'—'}</td></tr>`).join('')):empty('No entries in this period','Choose a different period or post your first transaction.')}<div class="table-footer">${r.ledger.length} journal lines · Debit: ${currency(r.ledger.reduce((s,l)=>s+l.debit,0))} · Credit: ${currency(r.ledger.reduce((s,l)=>s+l.credit,0))}</div></section>`;
 return head('A clearer picture of your business.','Financial reports that stay connected to every transaction.',`<div class="flex">${button(`${icon('print')} Print`,'print-report')}${button(`${icon('down')} Export CSV`,'export','primary')}</div>`,'REPORTS & INSIGHTS')+`<form id="report-filters" class="report-filters"><label>From<input name="start" type="date" value="${state.start}" required></label><label>To<input name="end" type="date" value="${state.end}" required></label><button class="btn primary">Apply period</button><span class="subtitle">Balance sheet and stock use the end date.</span></form><div class="tabs report-tabs">${[['pnl','Profit & loss'],['balance','Balance sheet'],['budget','Budget report'],['stock','Stock report'],['ledger','General ledger']].map(([key,label])=>`<button class="tab ${state.reportTab===key?'active':''}" data-action="report-tab" data-tab="${key}">${label}</button>`).join('')}</div>${content}`+footer()
}
function settingsPage(){const admin=state.user.role==='admin';return head('A workspace that works for you.','Manage access, protect your records, and keep things organized.','','WORKSPACE SETTINGS')+`<section class="panel mb"><div class="panel-head"><div><h2>Your account</h2><p>${esc(state.user.email)} · ${esc(state.user.role)}</p></div>${button('Change password','password')}</div></section>`+(admin?`<div class="role-grid"><div class="role-card"><h3>Business owner</h3><p>Create, edit, and archive master data. Record transactions, manage users, and view reports.</p></div><div class="role-card"><h3>Accountant</h3><p>Create master data, record transactions, and view reports. Existing master data is maintained by the owner.</p></div><div class="role-card"><h3>Contact</h3><p>View linked invoices, bills and statements. Submit payment details for staff approval.</p></div></div><section class="panel mb"><div class="panel-head"><h2>People & access</h2>${button(`${icon('plus')} Add user`,'new-user','primary')}</div>${table(['Name','Email','Role','Status',''],state.data.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td>${badge(u.role,u.role==='admin'?'green':'')}</td><td>${badge(u.active?'Active':'Disabled',u.active?'green':'')}</td><td>${u.id!==state.user.id?`<div class="flex">${button(u.active?'Disable':'Enable','toggle-user','small',`data-id="${u.id}"`)}${button('Reset password','reset-password','small',`data-id="${u.id}"`)}</div>`:'You'}</td></tr>`).join(''))}</section><section class="panel mb"><div class="panel-head"><div><h2>Your data belongs to you</h2><p>Download a consistent private export of records, users, and audit history.</p></div>${icon('shield')}</div><div class="settings-actions"><a class="btn" href="/api/backup">${icon('down')} Download database backup</a>${button('Accounting conventions','help')}</div></section><section class="panel"><div class="panel-head"><h2>Audit trail</h2><span class="subtitle">Latest 100 events</span></div>${table(['When (UTC)','Person','Action','Record','Details'],state.data.audit.map(a=>`<tr><td>${esc(a.created_at)}</td><td>${esc(a.user_name)}</td><td>${esc(a.action)}</td><td>${esc(a.entity)} ${a.entity_id?'#'+a.entity_id:''}</td><td class="audit-detail" title="${esc(a.detail)}">${esc(a.detail)||'—'}</td></tr>`).join(''))}</section>`:'')+footer()}
function field(label,name,type='text',value='',attrs={}){let attr=Object.entries(attrs).filter(([,v])=>v!==false).map(([k,v])=>`${k}="${esc(v===true?'':v)}"`).join(' ');return `<label class="field ${attrs.full?'full':''}">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${attr}></label>`}
function selectField(label,name,options,value='',placeholder='Select…'){return `<label class="field">${label}<select name="${name}" ${placeholder==='None (optional)'?'':'required'}><option value="">${placeholder}</option>${options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></label>`}
const typesOptions = a => a.map(x=>[x,x]);
const recordOptions = a => a.map(x=>[x.id,x.code?`${x.code} · ${x.name}`:x.name]);
function openModal(title,body,foot='',wide=false,form=false){const modal=$('#modal');modal.className=wide?'wide':'';modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${form?'<form id="modal-form">':''}<div class="modal-body">${body}<div class="form-error" id="modal-error" role="alert"></div></div>${foot?`<div class="modal-footer">${foot}</div>`:''}${form?'</form>':''}`;if(!modal.open)modal.showModal();modal.scrollTop=0}
function saveFooter(label='Save'){return `<button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary">${label}</button>`}
function masterForm(table,id=null){const x=id?find(table,id):{};state.form={type:'master',table,id};let html=field('Name','name','text',x.name,{required:true});const choices={contacts:['Customer','Vendor','Both'],products:['Goods','Service','Combo'],accounts:['Asset','Liability','Expense','Income','Capital'],journals:['Sales','Purchase','Bank','Cash','General'],analytics:['Income','Expense']};if(choices[table])html+=selectField('Type','type',typesOptions(choices[table]),x.type);
 if(table==='contacts'){html+=field('Email','email','email',x.email)+field('Mobile','mobile','tel',x.mobile)+field('City','city','text',x.city)+field('State','state','text',x.state)+field('Pincode','pincode','text',x.pincode)+field('Address','address','text',x.address)+`<label class="field full">Profile image<input type="file" name="profile" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP. Maximum 500 KB.</small>${x.image?`<img class="profile-preview" src="${esc(x.image)}" alt="Current profile">`:''}</label>`;if(!id)html+=field('Contact portal password (optional)','portal_password','password','',{minlength:10,autocomplete:'new-password',full:true});}
 if(table==='products')html+=field('Sales price (INR)','sales_price','number',(x.sales_price||0)/100,{required:true,min:0,step:'.01'})+field('Purchase cost (INR)','cost','number',(x.cost||0)/100,{required:true,min:0,step:'.01'})+field('Category','category','text',x.category);
 if(table==='accounts')html+=field('Account code','code','text',x.code,{required:true});
 if(table==='journals')html+=selectField('Default debit account','debit_account_id',recordOptions(active('accounts')),x.debit_account_id)+selectField('Default credit account','credit_account_id',recordOptions(active('accounts')),x.credit_account_id);
 if(table==='budgets')html+=field('Start date','start_date','date',x.start_date||today,{required:true})+field('End date','end_date','date',x.end_date||`${now.getFullYear()}-12-31`,{required:true})+field('Responsible person','responsible','text',x.responsible||state.user.name,{required:true})+selectField('Analytic account','analytic_id',recordOptions(active('analytics')),x.analytic_id)+field('Planned amount (INR)','planned','number',(x.planned||0)/100,{required:true,min:0,step:'.01'});
 openModal(`${id?'Edit':'Add'} ${masterTitles[table].toLowerCase()}`,`<div class="form-grid">${html}</div>${table==='contacts'&&!id?'<p class="subtitle">Set a portal password and email to let this contact sign in. They will see only their own documents.</p>':''}${table==='journals'?'<p class="subtitle">Sales: receivable → income. Purchase: expense → payable. Bank/Cash: use the matching asset as debit default.</p>':''}`,saveFooter(),false,true)
}
function orderForm(kind){const sale=kind==='sale';if(!active('contacts').some(c=>c.type==='Both'||c.type===(sale?'Customer':'Vendor'))||!active('products').length){openModal('A little preparation first',`<p class="subtitle">Add an active ${sale?'customer':'vendor'} contact and at least one product before creating this order.</p>`,button('Add contact','new-master','primary','data-table="contacts"')+button('Add product','new-master','','data-table="products"'));return}state.form={type:'order',kind};const journals=active('journals').filter(j=>j.type===(sale?'Sales':'Purchase'));openModal(`New ${sale?'sales':'purchase'} order`,`<div class="form-grid">${selectField(sale?'Customer':'Vendor','contact_id',recordOptions(active('contacts').filter(c=>c.type==='Both'||c.type===(sale?'Customer':'Vendor'))))}${selectField('Journal','journal_id',recordOptions(journals),journals[0]?.id)}${field('Order date','date','date',today,{required:true})}${field('Due date','due_date','date',localDate(new Date(now.getFullYear(),now.getMonth(),now.getDate()+30)),{required:true})}${selectField('Analytic account','analytic_id',recordOptions(active('analytics').filter(a=>a.type===(sale?'Income':'Expense'))),'','None (optional)')}</div><div class="section-title">Order items</div><div class="table-wrap"><table class="line-table"><thead><tr><th>Product</th><th>Quantity</th><th>Price (₹)</th><th>Tax %</th><th>Total</th><th></th></tr></thead><tbody id="order-lines"></tbody></table></div>${button(`${icon('plus')} Add line`,'add-line','text','type="button"')}<div id="order-totals" class="order-totals"></div><label class="field full mt">Notes<textarea name="notes" placeholder="Delivery instructions, payment terms, or a little context…"></textarea></label>`,saveFooter('Create draft order'),true,true);addOrderLine()}
function addOrderLine(){const options=active('products');const p=options[0];const row=document.createElement('tr');row.className='order-line';row.innerHTML=`<td><select class="line-input" name="product_id" required aria-label="Product">${options.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></td><td><input class="line-input qty" name="quantity" aria-label="Quantity" type="number" min="0.001" step=".001" value="1" required></td><td><input class="line-input price" name="unit_price" aria-label="Unit price" type="number" min="0" step=".01" value="${(state.form.kind==='sale'?p.sales_price:p.cost)/100}" required></td><td><input class="line-input tax" name="tax_rate" aria-label="Tax rate" type="number" min="0" max="100" step=".01" value="0" required></td><td class="num line-total"></td><td><button type="button" class="icon-btn" data-action="remove-line" aria-label="Remove line">${icon('close')}</button></td>`;$('#order-lines').append(row);calculateOrder()}
function orderLines(){return $$('.order-line').map(row=>Object.fromEntries($$('input,select',row).map(el=>[el.name,el.value])))}
function calculateOrder(){let subtotal=0,tax=0;$$('.order-line').forEach(row=>{const sub=Math.round(Number($('[name=quantity]',row).value)*Math.round(Number($('[name=unit_price]',row).value)*100));const t=Math.round(sub*Number($('[name=tax_rate]',row).value)/100);subtotal+=sub;tax+=t;$('.line-total',row).textContent=currency(sub+t)});$('#order-totals').innerHTML=`<div class="report-line"><span>Subtotal</span><span>${currency(subtotal)}</span></div><div class="report-line"><span>Tax</span><span>${currency(tax)}</span></div><div class="report-line total"><span>Total</span><span>${currency(subtotal+tax)}</span></div><p class="subtitle">Final totals are calculated on the server.</p>`}
function lineItems(items){return table(['Description','Qty','Unit price','Tax','Total'],items.map(l=>`<tr><td><strong>${esc(l.description)}</strong></td><td>${esc(l.quantity)}</td><td>${currency(l.unit_price)}</td><td>${esc(l.tax_rate)}% · ${currency(l.tax)}</td><td class="num"><strong>${currency(l.total)}</strong></td></tr>`).join(''))}
async function viewOrder(id){const {order:o,lines}=await api('/orders/'+id);let foot=button('Close','close');if(o.status==='draft')foot=button('Cancel order','cancel-order','danger',`data-id="${id}"`)+button(`Convert to ${o.kind==='sale'?'invoice':'vendor bill'}`,'post-order','primary',`data-id="${id}"`);const doc=state.data.documents.find(d=>d.order_id===id);if(doc)foot+=button('View '+doc.number,'view-document','primary',`data-id="${doc.id}"`);openModal(o.number,`<div class="doc-heading"><div><div class="eyebrow">${o.kind==='sale'?'SALES ORDER':'PURCHASE ORDER'}</div><h2>${esc(find('contacts',o.contact_id)?.name)}</h2><p class="subtitle">${badge(o.status)}</p></div><div class="doc-info">Order date: <strong>${displayDate(o.date)}</strong><br>Due date: <strong>${displayDate(o.due_date)}</strong><br>Journal: ${esc(find('journals',o.journal_id)?.name)}</div></div>${lineItems(lines)}<div class="order-totals"><div class="report-line"><span>Subtotal</span><span>${currency(o.subtotal)}</span></div><div class="report-line"><span>Tax</span><span>${currency(o.tax)}</span></div><div class="report-line total"><span>Total</span><span>${currency(o.total)}</span></div></div><p class="invoice-notes">${esc(o.notes)}</p>`,foot,true)}
async function postOrderForm(id){const {order:o}=await api('/orders/'+id);state.form={type:'post-order',id};openModal(o.kind==='sale'?'Post customer invoice':'Receive stock & post bill',`<div class="notice">This will create a permanent ${o.kind==='sale'?'customer invoice':'vendor bill'}, post a balanced journal entry, and ${o.kind==='sale'?'reduce':'increase'} stock. Verify the order before posting.</div><div class="form-grid">${field('Invoice date','date','date',o.date,{required:true})}${field('Due date','due_date','date',o.due_date,{required:true})}</div>`,saveFooter('Post '+(o.kind==='sale'?'invoice':'vendor bill')),false,true)}
async function viewDocument(id){const {document:d,order:o,contact:c,lines,payments}=await api('/documents/'+id);const pay=d.paid<d.total&&(state.user.role!=='contact'||d.kind==='sale');openModal(d.number,`<div id="invoice"><div class="doc-heading"><div><div class="invoice-brand">urban furniture</div><p class="subtitle">${d.kind==='sale'?'CUSTOMER INVOICE':'VENDOR BILL'}</p><h1 style="margin-top:14px">${d.number}</h1></div><div class="doc-info">${statusBadge(d)}<br>Issued: <strong>${displayDate(d.date)}</strong><br>Due: <strong>${displayDate(d.due_date)}</strong><br>Order: ${o.number}</div></div><div class="doc-info mb"><small>${d.kind==='sale'?'BILL TO':'VENDOR'}</small><br><strong>${esc(c.name)}</strong><br>${esc(c.address)}${c.address?'<br>':''}${esc([c.city,c.state,c.pincode].filter(Boolean).join(', '))}<br>${esc(c.email)} ${esc(c.mobile)}</div>${lineItems(lines)}<div class="order-totals"><div class="report-line"><span>Subtotal</span><span>${currency(o.subtotal)}</span></div><div class="report-line"><span>Tax</span><span>${currency(o.tax)}</span></div><div class="report-line"><span>Total</span><strong>${currency(d.total)}</strong></div><div class="report-line"><span>Paid</span><span>${currency(d.paid)}</span></div><div class="report-line total"><span>Amount due</span><span>${currency(d.total-d.paid)}</span></div></div>${o.notes?`<p class="invoice-notes">${esc(o.notes)}</p>`:''}${payments.length?`<div class="section-title">Payment history</div>${table(['Receipt','Date','Method','Reference','Amount'],payments.map(p=>`<tr><td>${p.number}</td><td>${displayDate(p.date)}</td><td>${p.method}</td><td>${esc(p.reference)}</td><td class="num">${currency(p.amount)}</td></tr>`).join(''))}`:''}<p class="subtitle mt">Thank you for doing business with Urban Furniture.</p></div>`,button(`${icon('print')} Print / save PDF`,'print')+(pay?button('Record payment','payment','primary',`data-id="${id}"`):''),true)}
function paymentForm(id){const d=state.data.documents.find(x=>x.id===id);state.form={type:'payment',id};openModal('Record '+(d.kind==='sale'?'receipt':'vendor payment'),`<div class="overview-banner"><div><strong>${d.number} · ${esc(d.contact_name)}</strong><p>Outstanding ${currency(d.total-d.paid)}</p></div></div><div class="form-grid">${field('Amount (INR)','amount','number',(d.total-d.paid)/100,{required:true,min:'.01',max:(d.total-d.paid)/100,step:'.01'})}${selectField('Payment method','method',typesOptions(['Bank','Cash']),'Bank')}${field('Payment date','date','date',today,{required:true,min:d.date})}${field('Reference','reference','text','')}</div><p class="subtitle mt">This records a payment in your books. Complete the bank transfer or cash exchange separately.</p>`,saveFooter('Record payment'),false,true)}
function entryForm(){state.form={type:'entry'};openModal('Post journal entry',`<div class="notice">Use this for owner investment and operating income or expenses. Receivable and payable control accounts are managed through invoices, bills, and payments.</div><div class="form-grid">${selectField('Journal','journal_id',recordOptions(active('journals')),active('journals').find(j=>j.type==='General')?.id)}${field('Date','date','date',today,{required:true})}${field('Reference','reference','text','',{required:true,full:true})}</div><div class="section-title">Journal items</div><div class="table-wrap"><table class="line-table"><thead><tr><th>Account</th><th>Analytic (optional)</th><th>Debit (₹)</th><th>Credit (₹)</th><th></th></tr></thead><tbody id="entry-lines"></tbody></table></div>${button(`${icon('plus')} Add line`,'add-entry-line','text','type="button"')}<div id="entry-totals" class="order-totals"></div>`,saveFooter('Post balanced entry'),true,true);addEntryLine();addEntryLine()}
function addEntryLine(){const row=document.createElement('tr');row.className='entry-line';row.innerHTML=`<td><select class="line-input" name="account_id" aria-label="Account" required><option value="">Select account</option>${active('accounts').filter(a=>!['receivable','payable'].includes(a.system_key)).map(a=>`<option value="${a.id}">${esc(a.code+' · '+a.name)}</option>`).join('')}</select></td><td><select class="line-input" name="analytic_id" aria-label="Analytic account"><option value="">None</option>${active('analytics').map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></td><td><input class="line-input price" name="debit" aria-label="Debit" type="number" min="0" step=".01" value="0" required></td><td><input class="line-input price" name="credit" aria-label="Credit" type="number" min="0" step=".01" value="0" required></td><td><button class="icon-btn" data-action="remove-entry-line" type="button" aria-label="Remove line">${icon('close')}</button></td>`;$('#entry-lines').append(row);calculateEntry()}
function calculateEntry(){const sum=name=>$$(`.entry-line [name=${name}]`).reduce((s,e)=>s+Math.round(Number(e.value)*100),0);const debit=sum('debit'),credit=sum('credit');$('#entry-totals').innerHTML=`<div class="report-line"><span>Debit</span><span>${currency(debit)}</span></div><div class="report-line"><span>Credit</span><span>${currency(credit)}</span></div><div class="report-line total"><span>Difference</span><span>${currency(debit-credit)}</span></div>`}
async function viewEntry(id){const {entry:e,lines}=await api('/entries/'+id);openModal(e.number,`<div class="doc-info mb">${displayDate(e.date)} · ${esc(e.reference)}<br>${esc(find('journals',e.journal_id)?.name)} · ${esc(e.source)}</div>${table(['Account','Debit','Credit'],lines.map(l=>`<tr><td><strong>${esc(l.code+' · '+l.account_name)}</strong></td><td class="num">${l.debit?currency(l.debit):'—'}</td><td class="num">${l.credit?currency(l.credit):'—'}</td></tr>`).join(''))}<div class="balance-foot">${icon('check')} Balanced · Total debit and credit ${currency(lines.reduce((s,l)=>s+l.debit,0))}</div>`,button('Close','close'),true)}
function userForm(){state.form={type:'user'};openModal('Add workspace user',`<div class="form-grid">${field('Full name','name','text','',{required:true})}${field('Email','email','email','',{required:true})}${selectField('Role','role',typesOptions(['accountant','admin','contact']),'accountant')}${selectField('Linked contact (contact role only)','contact_id',recordOptions(active('contacts')),'','None (optional)')}${field('Initial password','password','password','',{required:true,minlength:10,autocomplete:'new-password',full:true})}</div><p class="subtitle mt">Share initial credentials securely. Users can change their password in account settings.</p>`,saveFooter('Create user'),false,true)}
function passwordForm(id=null){state.form={type:id?'reset-password':'password',id};openModal(id?'Reset user password':'Change your password',`<div class="form-grid">${id?'':field('Current password','current','password','',{required:true,full:true,autocomplete:'current-password'})}${field('New password','password','password','',{required:true,minlength:10,full:true,autocomplete:'new-password'})}</div>`,saveFooter('Update password'),false,true)}
function help(){openModal('Your workspace, explained',`<div class="doc-info"><h3>1. Set your foundations</h3><p>Complete the company profile, then add contacts and products with their GST and HSN/SAC details.</p><br><h3>2. Receive and sell</h3><p>Post a purchase order to receive goods and create a vendor bill. Post a sales order to issue stock and create an invoice. The backend calculates CGST + SGST, IGST, or exempt totals.</p><br><h3>3. Keep your books in balance</h3><p>Record full or partial Cash/Bank settlements. Contact submissions stay pending until staff approval. Every posting creates a balanced journal entry; posted transactions are immutable.</p><br><h3>4. Find the bigger picture</h3><p>Review ageing, cash forecasts, statements, balance sheet, profit & loss, budgets, stock, and general ledger. Open browsers update after committed changes.</p><br><h3>Accounting conventions</h3><p>INR, integer paise, and line-level half-up tax rounding. Purchases are expensed at bill posting. Combos are whole stock items. Payments are accounting records; no money-transfer gateway is connected.</p><br><h3>Data ownership</h3><p>The owner can download a private application-data backup in Settings. PostgreSQL is the active database for this workspace.</p></div>`,button('Got it','close','primary'),true)}
async function submitModal(form){const data=Object.fromEntries(new FormData(form));const f=state.form;
 if(f.type==='master'){if(f.table==='contacts'){const file=$('[name=profile]',form).files[0];data.image=f.id?find('contacts',f.id).image:'';if(file){if(file.size>500000)throw Error('Profile image must be under 500 KB.');data.image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read image.'));reader.readAsDataURL(file)})}delete data.profile}await api(`/masters/${f.table}${f.id?'/'+f.id:''}`,f.id?'PATCH':'POST',data)}
 else if(f.type==='order')await api('/orders','POST',{...data,kind:f.kind,lines:orderLines()});
 else if(f.type==='post-order')await api(`/orders/${f.id}/post`,'POST',data);
 else if(f.type==='payment')await api(`/documents/${f.id}/payments`,'POST',data);
 else if(f.type==='entry')await api('/entries','POST',{...data,lines:$$('.entry-line').map(row=>Object.fromEntries($$('select,input',row).map(el=>[el.name,el.value])))});
 else if(f.type==='user')await api('/users','POST',data);
 else if(f.type==='password')await api('/password','POST',data);
 else if(f.type==='reset-password')await api('/users/'+f.id,'PATCH',data);
 $('#modal').close();await refresh(f.type==='payment'?'Payment recorded. Your books are updated.':f.type==='post-order'?'Posted. Stock and ledgers are updated.':'Saved successfully.');
 if(f.type==='payment')await viewDocument(f.id)
}
document.addEventListener('submit',async e=>{if(!['auth-form','modal-form','report-filters'].includes(e.target.id))return;e.preventDefault();const form=e.target,submit=$('[type=submit]',form)||$('button',form);if(submit?.disabled)return;if(submit)submit.disabled=true;try{if(form.id==='auth-form'){const data=Object.fromEntries(new FormData(form));await api(form.dataset.setup==='true'?'/setup':'/login','POST',data);await boot()}else if(form.id==='report-filters'){const data=Object.fromEntries(new FormData(form));const r=await api(`/reports?start=${data.start}&end=${data.end}`);state.start=data.start;state.end=data.end;state.report=r;render()}else await submitModal(form)}catch(err){const target=form.id==='auth-form'?$('#auth-error'):$('#modal-error');if(target&&form.id!=='report-filters')target.textContent=err.message;else toast(err.message)}finally{if(submit)submit.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;state.query=e.target.value;$('#page').innerHTML=renderPage();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(e.target.closest('.order-line'))calculateOrder();if(e.target.closest('.entry-line'))calculateEntry()});
document.addEventListener('change',e=>{if(e.target.matches('.order-line [name=product_id]')){const p=find('products',e.target.value);$('[name=unit_price]',e.target.closest('tr')).value=(state.form.kind==='sale'?p.sales_price:p.cost)/100;calculateOrder()}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id),table=b.dataset.table;if(b.disabled)return;try{switch(a){case'retry':await boot();break;case'navigate':state.page=b.dataset.page;state.filter='all';state.query='';location.hash=state.page;render();break;case'mobile-nav':$('.sidebar').classList.toggle('open');break;case'filter':state.filter=b.dataset.filter;$('#page').innerHTML=renderPage();break;case'report-tab':state.reportTab=b.dataset.tab;$('#page').innerHTML=renderPage();break;case'logout':await api('/logout','POST',{});state.data={};state.user=null;await boot();break;case'close':$('#modal').close();break;case'new-master':masterForm(table);break;case'edit-master':masterForm(table,id);break;case'archive':{const x=find(table,id);if(x.active){state.form={type:'archive',table,id};openModal('Archive '+esc(x.name)+'?',`<p class="subtitle">This record will no longer be selectable in new transactions. Existing history is preserved. You can restore it later.</p>`,button('Cancel','close')+button('Archive record','confirm-archive','danger',`data-table="${table}" data-id="${id}"`))}else{await api(`/masters/${table}/${id}`,'PATCH',{active:true});await refresh('Record restored.')}break}case'confirm-archive':b.disabled=true;await api(`/masters/${table}/${id}`,'PATCH',{active:false});$('#modal').close();await refresh('Record archived.');break;case'new-order':orderForm(b.dataset.kind);break;case'add-line':addOrderLine();break;case'remove-line':b.closest('tr').remove();calculateOrder();break;case'view-order':await viewOrder(id);break;case'post-order':await postOrderForm(id);break;case'cancel-order':openModal('Cancel draft order?',`<p class="subtitle">The draft will be marked cancelled. No ledger or stock entries will be created.</p>`,button('Keep order','close')+button('Cancel order','confirm-cancel','danger',`data-id="${id}"`));break;case'confirm-cancel':b.disabled=true;await api(`/orders/${id}/cancel`,'POST',{});$('#modal').close();await refresh('Draft order cancelled.');break;case'view-document':await viewDocument(id);break;case'payment':paymentForm(id);break;case'new-entry':entryForm();break;case'add-entry-line':addEntryLine();break;case'remove-entry-line':b.closest('tr').remove();calculateEntry();break;case'view-entry':await viewEntry(id);break;case'new-user':userForm();break;case'toggle-user':b.disabled=true;await api('/users/'+id,'PATCH',{active:!state.data.users.find(x=>x.id===id).active});await refresh('User access updated.');break;case'password':passwordForm();break;case'reset-password':passwordForm(id);break;case'help':help();break;case'print':window.print();break;case'print-report':document.body.classList.add('print-report');window.print();document.body.classList.remove('print-report');break;case'export':{const kind={pnl:'accounts',balance:'accounts',budget:'budgets',stock:'stock',ledger:'ledger'}[state.reportTab];location.href=`/api/reports/export?kind=${kind}&start=${state.start}&end=${state.end}`;break}}}catch(err){if($('#modal').open&&$('#modal-error'))$('#modal-error').textContent=err.message;else toast(err.message)}finally{b.disabled=false}});
window.addEventListener('hashchange',()=>{if(state.user){const page=location.hash.slice(1);if(state.user.role==='contact'&&!['portal','settings'].includes(page))return;if(pageNames[page]&&state.page!==page){state.page=page;state.query='';state.filter='all';render()}}});
// Boot is coordinated by workspace.js after the live workspace layer is loaded.
